import{_ as r,c as o,o as n,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Экспорт","description":"","frontmatter":{"title":"Экспорт"},"headers":[],"relativePath":"ru/logs/export.md","filePath":"ru/logs/export.md"}'),e={name:"ru/logs/export.md"};function g(a,t,l,i,d,h){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="экспорт" tabindex="-1">Экспорт <a class="header-anchor" href="#экспорт" aria-label="Permalink to &quot;Экспорт&quot;">​</a></h1><p>События вкладки <strong>Logs</strong> можно сохранить в <strong>HTML</strong>-отчёт и открыть в любом браузере. Это удобно для баг-репортов, передачи сценария коллегам и анализа вне страницы.</p><p>Общие сведения о вкладке: <a href="./general.html">Работа с логами</a>.</p><hr><h2 id="формат-экспорта" tabindex="-1">Формат экспорта <a class="header-anchor" href="#формат-экспорта" aria-label="Permalink to &quot;Формат экспорта&quot;">​</a></h2><p>Любой экспорт — один <strong>HTML</strong>-файл: статический отчёт, который открывается в браузере. Отдельного экспорта в JSON нет.</p><p>Данные внутри отчёта компактные, как и в живом логе (см. <a href="./general.html#how-events-are-stored">Как хранятся события</a>): изменения стора — диффы, запрос и ответ используют одну сетевую запись, одинаковые тела хранятся один раз, а одинаковые значения в любом событии хранятся один раз как общий снимок. Заголовки, состояния Before / After, значения снимков и данные запроса и ответа восстанавливаются при открытии отчёта.</p><p>Встроенные данные используют версию формата 1.</p><hr><h2 id="что-именно-экспортируется" tabindex="-1">Что именно экспортируется <a class="header-anchor" href="#что-именно-экспортируется" aria-label="Permalink to &quot;Что именно экспортируется&quot;">​</a></h2><h3 id="export-logs" tabindex="-1">Export Logs <a class="header-anchor" href="#export-logs" aria-label="Permalink to &quot;Export Logs&quot;">​</a></h3><ul><li>Без выбора — все события, видимые в таблице с учётом <strong>Search</strong> и фильтра <strong>Type</strong>.</li><li>С выбором — только строки, отмеченные в колонке чекбоксов; кнопка показывает <strong>Export Logs (n)</strong>.</li><li>Сетевые события всегда экспортируются парой: если в фильтр или выбор попал только <strong>Send request</strong> или только <strong>Receive response</strong> запроса, второе событие тоже добавляется в файл. Кадр WebSocket остаётся тем событием, которое выбрано.</li></ul><p>Кнопка неактивна, пока в отфильтрованном списке нет ни одного события.</p><h3 id="одно-событие" tabindex="-1">Одно событие <a class="header-anchor" href="#одно-событие" aria-label="Permalink to &quot;Одно событие&quot;">​</a></h3><p><strong>Export event</strong> в меню <strong>⋮</strong> шапки детализации или в контекстном меню строки экспортирует одно событие.</p><p>Для сетевых событий пункт называется <strong>Export request &amp; response</strong>: события <strong>Send request</strong> и <strong>Receive response</strong> одного запроса экспортируются вместе в одном файле, поэтому запрос и ответ никогда не разделяются. Событие WebSocket экспортируется само по себе.</p><h3 id="изменения-pinia-при-частичном-экспорте" tabindex="-1">Изменения Pinia при частичном экспорте <a class="header-anchor" href="#изменения-pinia-при-частичном-экспорте" aria-label="Permalink to &quot;Изменения Pinia при частичном экспорте&quot;">​</a></h3><p>Событие <strong>Change store</strong> — дифф относительно предыдущего события того же стора. Если предыдущее событие не попало в экспорт (выбор строк, фильтр или одно событие), экспортируемое изменение дополнительно несёт полное состояние после него и старые значения изменённых полей, поэтому <strong>Before</strong> / <strong>After</strong> доступны и в файле.</p><h3 id="фаилы" tabindex="-1">Файлы <a class="header-anchor" href="#фаилы" aria-label="Permalink to &quot;Файлы&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Экспорт</th><th>Имя файла</th></tr></thead><tbody><tr><td><strong>Export Logs</strong></td><td><code>logs_&lt;дата&gt;_&lt;время&gt;.html</code></td></tr><tr><td>Сетевая пара</td><td><code>log_network_&lt;дата&gt;_&lt;время&gt;.html</code></td></tr><tr><td>Другое одиночное событие</td><td><code>log_&lt;тип&gt;_&lt;дата&gt;_&lt;время&gt;.html</code></td></tr></tbody></table><p>Данные маскируются в момент записи, поэтому в файлах те же замаскированные значения, что и в интерфейсе (см. <a href="./settings.html#data-masking">Настройки логов</a>).</p><hr><h2 id="html-отчет" tabindex="-1">HTML-отчёт <a class="header-anchor" href="#html-отчет" aria-label="Permalink to &quot;HTML-отчёт&quot;">​</a></h2><p><strong>HTML</strong>-отчёт — один самодостаточный файл: стили, скрипты, иконка приложения и данные событий встроены внутрь. Отчёт в тёмной теме, не загружает внешние ресурсы и открывается с диска без интернета.</p><h3 id="боковая-панель" tabindex="-1">Боковая панель <a class="header-anchor" href="#боковая-панель" aria-label="Permalink to &quot;Боковая панель&quot;">​</a></h3><ul><li><strong>Report</strong> — <strong>Overview</strong> и <strong>All events</strong> с общим количеством;</li><li>разделы по типам со счётчиками: <strong>Network</strong> (<strong>Send request</strong>, <strong>Receive response</strong>), <strong>WebSocket</strong> (<strong>WebSocket open</strong>, <strong>WebSocket sent</strong>, <strong>WebSocket received</strong>, <strong>WebSocket closed</strong>), <strong>Components</strong> (<strong>Change props</strong>, <strong>Emit</strong>), <strong>Pinia</strong> (<strong>Change store</strong>, <strong>Store action</strong>), <strong>Page</strong> (<strong>Navigation</strong>, <strong>JS error</strong>);</li><li>внизу — <strong>Download Vue Inspector</strong> со ссылкой на страницу проекта.</li><li>над ней — <strong>Support Vue Inspector</strong>: <strong>Monthly support</strong> открывает Boosty, <strong>Donate with USDT</strong> показывает адрес Tron (TRC-20), QR-код и кнопку <strong>Copy address</strong>.</li></ul><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>Сводные карточки: <strong>Events</strong>, <strong>Errors</strong>, <strong>Failed requests</strong>, время первого и последнего события, длительность; счётчики по типам; сведения об экспорте. <strong>Generator</strong> — <strong>Vue Inspector Extension</strong> или <strong>Vue Inspector Bookmarklet</strong>, в зависимости от режима, в котором создан файл.</p><p>В шапке первая строка — <strong>Vue Inspector</strong> и этот режим в рамке тега, вторая — <strong>Logs report</strong>. Число событий и время экспорта стоят справа и выровнены по центру этих двух строк.</p><p>Карточки <strong>Events</strong>, <strong>Errors</strong> и <strong>Failed requests</strong> кликабельны: они открывают <strong>All events</strong> с соответствующим фильтром. Активный фильтр показывается чипом над списком; клик по чипу снимает фильтр.</p><h3 id="список-событии-и-детализация" tabindex="-1">Список событий и детализация <a class="header-anchor" href="#список-событии-и-детализация" aria-label="Permalink to &quot;Список событий и детализация&quot;">​</a></h3><ul><li>Поиск в верхней панели; при включённом <strong>in data</strong> поиск идёт и по данным событий.</li><li>На <strong>All events</strong> есть выпадающий список <strong>Type</strong> с чекбоксами — тот же фильтр, что на вкладке <strong>Logs</strong>. По умолчанию включены все типы. <strong>Select all</strong> и <strong>Clear</strong> включают или выключают весь список. Если выключены все типы, список пуст. Фильтр действует на этой странице вместе с поиском и чипом <strong>Errors</strong> / <strong>Failed requests</strong> и не меняет разделы боковой панели.</li><li>Клик по строке открывает детализацию с теми же вкладками, что и в приложении (<strong>Overview</strong>, <strong>Params</strong>, <strong>Headers</strong>, <strong>Body</strong>, <strong>Changes</strong>, <strong>Before</strong> / <strong>After</strong>, <strong>State</strong>, <strong>Raw</strong> и т.д.). У каждого блока JSON и текста сверху одна и та же строка: <strong>Find</strong>, стрелки к предыдущему и следующему совпадению, счётчик совпадений и <strong>Copy</strong>. JSON форматируется с отступами и подсвечивается, в том числе обрезанное тело. <strong>Find</strong> ищет по всему блоку и выделяет совпадения; Enter и Shift+Enter переходят между ними, Esc очищает поле. <strong>Copy</strong> копирует сохранённый текст. Пока открыта детализация с таким блоком, Ctrl+F (Cmd+F) переводит фокус в его поле <strong>Find</strong> в любой раскладке; повторное Ctrl+F открывает поиск браузера. Блок больше <strong>200 KB</strong> занимает всю область детализации и держит в странице только видимые строки, поэтому весь его текст видит только <strong>Find</strong>. Блоки меньше этого размера находятся в странице целиком, и поиск браузера работает и по ним.</li><li>Бинарный ответ показывает то же жёлтое уведомление, что и обрезанное тело, <em>Binary response received. Body not included in report.</em>, над строкой типа (<code>image/jpeg (986.2 KB)</code> и <strong>Binary</strong>).</li><li><strong>WebSocket open</strong>, <strong>WebSocket sent</strong>, <strong>WebSocket received</strong> и <strong>WebSocket closed</strong> вынесены в отдельный раздел <strong>WebSocket</strong>. Сообщение, если это JSON, показывается с отступами. Над блоком стоит строка <strong>Sent</strong> или <strong>Received</strong> и размер, тем же шрифтом, что тип и вес бинарного файла. <strong>WebSocket closed</strong> разбирает историю на такие же отдельные сообщения. Если на вкладке несколько сообщений, над ними стоит одна строка <strong>Find</strong>, которая остаётся видна при прокрутке: она ищет сразу по всем сообщениям, счётчик и стрелки идут по совпадениям во всех сообщениях подряд, а у каждого сообщения остаётся своя <strong>Copy</strong>. <strong>Overview</strong> показывает код закрытия, причину и <strong>No automatic reconnect</strong>, если это удалось определить.</li><li>Для сетевых событий <strong>Request</strong> или <strong>Response</strong> в шапке детализации переключает между запросом и его ответом. У кадра или открытия WebSocket кнопка <strong>Closed</strong>, у закрытия — <strong>Opened</strong>.</li><li><strong>Locate</strong> открывает <strong>All events</strong> и прокручивает список так, чтобы это событие было в видимой области, так же как <strong>Request</strong> / <strong>Response</strong> показывает парное событие. Если его тип был выключен, тип включается, чтобы событие осталось в списке. Когда панель детализации закрывает список, <strong>Locate</strong> ещё и закрывает панель, чтобы событие было видно в списке.</li><li>Панель детализации закрывается стрелкой слева (тот же элемент, что в приложении) или клавишей <strong>Esc</strong>.</li><li><strong>↑ / ↓</strong> — переход между событиями.</li><li>Выбранный раздел и событие сохраняются в адресе (<code>#…</code>): ссылкой на конкретное событие можно поделиться, и она переживает перезагрузку.</li><li>На узком экране список разделов открывается кнопкой меню. Его закрывают выбор раздела и нажатие за пределами панели. Строки событий показывают цветную полосу типа.</li></ul><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./general.html">Работа с логами</a></li><li><a href="./settings.html">Настройки логов</a></li><li><a href="/qa-tools/docs/ru/network/export.html">Экспорт коллекций</a></li></ul>',35)])])}const u=r(e,[["render",g]]);export{p as __pageData,u as default};
